// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  interpolateColors,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading
const { fontFamily: montserratFamily } = loadMontserrat();

// Utility for precise typography spacing estimation
const getCharWidth = (char: string): number => {
  if (/[ijlI.,|1]/.test(char)) return 0.28;
  if (/[rft! \-]/.test(char)) return 0.4;
  if (/[s]/.test(char)) return 0.5;
  if (/[mwMW]/.test(char)) return 0.95;
  if (/[A-Z]/.test(char)) return 0.72;
  if (/[0-9]/.test(char)) return 0.6;
  return 0.62;
};

const estimateWidthEm = (text: string): number => {
  let w = 0;
  for (let i = 0; i < text.length; i++) {
    w += getCharWidth(text[i]);
  }
  return w;
};



export type KineticTypographyProps = Record<string, any>;

const KineticTypography: React.FC<KineticTypographyProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,

  abbreviation = "ROI",
  fullPhrase = "Return On Investment",

  fontSize = 120,
  abbreviationColor = "#ffffff",
  fullPhraseColor = "#a0a0a0",
  fadeFromBlack = false,

  abbreviationTracking = 10,
  wordSpacing = 40,

  holdDurationFrames = 30,
  staggerFrames = 8,

  overshootIntensity = 40,

  revealMotionType = "fade",
  motionDistance = 50,
  preventClipping = true,
  widthCorrectionEm = 0.2,

  enableMotionBlur = true,
  glowIntensity = 0,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Parse background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Derive layout data
  const chars = abbreviation.replace(/\s/g, "").split("");
  const words = fullPhrase.split(" ").filter((w) => w.trim().length > 0);
  const maxLength = Math.max(chars.length, words.length);

  const pairs = Array.from({ length: maxLength }).map((_, i) => {
    const char = chars[i] || "";
    const word = words[i] || "";

    let anchor = char;
    let rest = "";

    if (char && word) {
      rest = word.substring(1);
    } else if (char && !word) {
      anchor = char;
      rest = "";
    } else if (!char && word) {
      anchor = word.charAt(0);
      rest = word.substring(1);
    }

    return { anchor, rest };
  });

  // Calculate Spring Physics Based on Overshoot Slider
  const damping = interpolate(overshootIntensity, [0, 100], [20, 8]);
  const stiffness = interpolate(overshootIntensity, [0, 100], [100, 140]);

  // Global progress dictates the tracking/spacing between word blocks
  const globalProgress = spring({
    frame: frame - holdDurationFrames,
    fps,
    config: { damping, stiffness },
  });

  const currentGap = interpolate(
    globalProgress,
    [0, 1],
    [abbreviationTracking, wordSpacing]
  );

  // Cinematic slow scale over the entire duration
  const cinematicScale = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [1, 1.08],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: montserratFamily,
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          gap: `${currentGap}px`,
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${cinematicScale})`,
          transition: "none",
        }}
      >
        {pairs.map((pair, i) => {
          const delay = holdDurationFrames + i * staggerFrames;
          const itemProgress = spring({
            frame: frame - delay,
            fps,
            config: { damping, stiffness },
          });

          // Compute exact width for perfect spacing when in full phrase
          const baseWidth = estimateWidthEm(pair.rest);
          const targetWidthEm = baseWidth > 0 ? baseWidth + widthCorrectionEm : 0;
          const currentWidthEm = itemProgress * targetWidthEm;
          const safeWidthEm = Math.max(0, currentWidthEm);

          // Fade & Motion Blur computations
          const opacityValue = interpolate(itemProgress, [0, 0.6], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          const blurValue = enableMotionBlur
            ? interpolate(itemProgress, [0, 0.5, 1], [0, 8, 0], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              })
            : 0;
            
          const clampedProgress = Math.max(0, Math.min(1, itemProgress));
          const currentTextColor = fadeFromBlack
            ? interpolateColors(clampedProgress, [0, 1], ["#000000", fullPhraseColor])
            : fullPhraseColor;

          // Motion Reveal computations
          const distanceEm = motionDistance / 100;
          const slideOutEm = interpolate(itemProgress, [0, 1], [-distanceEm, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const slideUpEm = interpolate(itemProgress, [0, 1], [distanceEm, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const scaleValue = interpolate(itemProgress, [0, 1], [1 - (distanceEm / 2), 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          let tx = 0;
          let ty = 0;
          let sc = 1;

          if (revealMotionType === "slide-right") tx = slideOutEm;
          if (revealMotionType === "slide-up") ty = slideUpEm;
          if (revealMotionType === "scale") sc = scaleValue;

          // Shadow depth formatting
          const abbreviationShadow =
            glowIntensity > 0
              ? `0 0 ${glowIntensity}px ${abbreviationColor}, 0 0 ${glowIntensity * 2}px ${abbreviationColor}`
              : undefined;

          const phraseShadow =
            glowIntensity > 0
              ? `0 0 ${glowIntensity}px ${currentTextColor}, 0 0 ${glowIntensity * 2}px ${currentTextColor}`
              : undefined;

          return (
            <div
              key={i}
              style={{
                display: "flex",
                flexDirection: "row",
                alignItems: "center",
                transition: "none",
              }}
            >
              {/* Anchor Character */}
              <div
                style={{
                  color: abbreviationColor,
                  fontSize: `${fontSize}px`,
                  fontWeight: 800,
                  textShadow: abbreviationShadow,
                  zIndex: 2,
                  transition: "none",
                }}
              >
                {pair.anchor}
              </div>

              {/* Emerging Associated Word */}
              <div
                style={{
                  width: `${safeWidthEm}em`,
                  opacity: opacityValue,
                  overflow: preventClipping ? "visible" : "hidden",
                  whiteSpace: "nowrap",
                  color: currentTextColor,
                  fontSize: `${fontSize}px`,
                  fontWeight: 800,
                  textShadow: phraseShadow,
                  filter: blurValue > 0 ? `blur(${blurValue}px)` : "none",
                  padding: "0.5em 0", // Prevents vertical clipping of large glows
                  margin: "-0.5em 0", // Rebalances the padding offset logically
                  display: "flex",
                  alignItems: "center",
                  zIndex: 1,
                  transition: "none",
                }}
              >
                <span
                  style={{
                    display: "inline-block",
                    transform: `translate(${tx}em, ${ty}em) scale(${sc})`,
                    transformOrigin: "left center",
                    transition: "none",
                  }}
                >
                  {pair.rest}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default KineticTypography;